SELECT s.id, s.device, t.duration_sec_range, t.latest_event_time FROM sessions s LEFT JOIN (SELECT session_id, MAX(duration_sec) - MIN(duration_sec) AS duration_sec_range, MAX(event_time) AS latest_event_time FROM web_events GROUP BY session_id) t ON s.id = t.session_id WHERE t.duration_sec_range > 41
